PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,password TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS organizations(id INTEGER PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memberships(user_id INTEGER REFERENCES users(id),org_id INTEGER REFERENCES organizations(id),role TEXT NOT NULL CHECK(role IN ('owner','manager','worker')),PRIMARY KEY(user_id,org_id));
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,org_id INTEGER REFERENCES organizations(id),expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS properties(id INTEGER PRIMARY KEY,org_id INTEGER NOT NULL REFERENCES organizations(id),name TEXT NOT NULL,address TEXT NOT NULL DEFAULT '',kind TEXT NOT NULL,occupancy TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0, UNIQUE(org_id,id));
CREATE TABLE IF NOT EXISTS items(id INTEGER PRIMARY KEY,org_id INTEGER NOT NULL,property_id INTEGER NOT NULL,name TEXT NOT NULL,room TEXT NOT NULL,category TEXT NOT NULL,needed INTEGER NOT NULL CHECK(needed>=0),quantity INTEGER NOT NULL CHECK(quantity>=0),damaged INTEGER NOT NULL CHECK(damaged BETWEEN 0 AND quantity), UNIQUE(org_id,id), FOREIGN KEY(org_id,property_id) REFERENCES properties(org_id,id));
CREATE TABLE IF NOT EXISTS issues(id INTEGER PRIMARY KEY,org_id INTEGER NOT NULL,property_id INTEGER NOT NULL,item_id INTEGER,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',priority TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('Aberta','Em andamento','Aguardando conferência','Resolvida','Cancelada')),due TEXT,created TEXT NOT NULL, UNIQUE(org_id,id), FOREIGN KEY(org_id,property_id) REFERENCES properties(org_id,id),FOREIGN KEY(org_id,item_id) REFERENCES items(org_id,id));
CREATE UNIQUE INDEX IF NOT EXISTS one_restock_issue ON issues(org_id,item_id) WHERE item_id IS NOT NULL AND status NOT IN ('Resolvida','Cancelada');
CREATE TABLE IF NOT EXISTS purchases(id INTEGER PRIMARY KEY,org_id INTEGER NOT NULL,item_id INTEGER NOT NULL,issue_id INTEGER,quantity INTEGER NOT NULL CHECK(quantity>0),received INTEGER NOT NULL DEFAULT 0 CHECK(received BETWEEN 0 AND quantity),cost INTEGER NOT NULL DEFAULT 0 CHECK(cost>=0),paid INTEGER NOT NULL DEFAULT 0 CHECK(paid IN (0,1)),status TEXT NOT NULL CHECK(status IN ('Solicitada','Aprovada','Parcialmente recebida','Recebida','Cancelada')),created TEXT NOT NULL,UNIQUE(org_id,id),FOREIGN KEY(org_id,item_id) REFERENCES items(org_id,id),FOREIGN KEY(org_id,issue_id) REFERENCES issues(org_id,id));
CREATE TABLE IF NOT EXISTS finance(id INTEGER PRIMARY KEY,org_id INTEGER NOT NULL,property_id INTEGER NOT NULL,purchase_id INTEGER,kind TEXT NOT NULL CHECK(kind IN ('Receita','Despesa')),title TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),date TEXT NOT NULL,UNIQUE(org_id,purchase_id),FOREIGN KEY(org_id,property_id) REFERENCES properties(org_id,id),FOREIGN KEY(org_id,purchase_id) REFERENCES purchases(org_id,id));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,org_id INTEGER NOT NULL REFERENCES organizations(id),user_id INTEGER NOT NULL REFERENCES users(id),action TEXT NOT NULL,details TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mutations(org_id INTEGER NOT NULL REFERENCES organizations(id),key TEXT NOT NULL,route TEXT NOT NULL,body TEXT NOT NULL,response TEXT NOT NULL,PRIMARY KEY(org_id,key));
CREATE INDEX IF NOT EXISTS item_property ON items(org_id,property_id);
CREATE INDEX IF NOT EXISTS issue_org_status ON issues(org_id,status);
CREATE INDEX IF NOT EXISTS finance_org_date ON finance(org_id,date);
CREATE TABLE IF NOT EXISTS extra_records(id INTEGER PRIMARY KEY,org_id INTEGER NOT NULL REFERENCES organizations(id),module TEXT NOT NULL,property_id INTEGER,record TEXT NOT NULL,issue_id INTEGER,expense_id INTEGER,FOREIGN KEY(org_id,property_id) REFERENCES properties(org_id,id),FOREIGN KEY(org_id,issue_id) REFERENCES issues(org_id,id));
CREATE INDEX IF NOT EXISTS extra_scope ON extra_records(org_id,module);
CREATE TABLE IF NOT EXISTS stock(id INTEGER PRIMARY KEY,org_id INTEGER NOT NULL REFERENCES organizations(id),title TEXT NOT NULL,category TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>=0),minimum INTEGER NOT NULL CHECK(minimum>=0));
CREATE TABLE IF NOT EXISTS billing_customers(org_id INTEGER PRIMARY KEY REFERENCES organizations(id),provider_id TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS billing_orders(id TEXT PRIMARY KEY,org_id INTEGER NOT NULL REFERENCES organizations(id),plan TEXT NOT NULL,amount INTEGER NOT NULL,provider_id TEXT UNIQUE,invoice TEXT,status TEXT NOT NULL DEFAULT 'CREATING',created TEXT NOT NULL,expires INTEGER);
CREATE TABLE IF NOT EXISTS ai_usage(org_id INTEGER NOT NULL REFERENCES organizations(id),day TEXT NOT NULL,requests INTEGER NOT NULL,PRIMARY KEY(org_id,day));
CREATE TABLE IF NOT EXISTS reservations(id INTEGER PRIMARY KEY, org_id INTEGER NOT NULL, property_id INTEGER NOT NULL, guest TEXT NOT NULL, arrival TEXT NOT NULL, departure TEXT NOT NULL CHECK(arrival<departure), status TEXT NOT NULL CHECK(status IN ('Confirmada','Concluída','Cancelada')), notes TEXT NOT NULL DEFAULT '', FOREIGN KEY(org_id,property_id) REFERENCES properties(org_id,id));
CREATE INDEX IF NOT EXISTS reservation_dates ON reservations(org_id,property_id,arrival,departure,status);
CREATE TABLE IF NOT EXISTS receivables(id INTEGER PRIMARY KEY, org_id INTEGER NOT NULL, property_id INTEGER NOT NULL, title TEXT NOT NULL, payer TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>0), due TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('Aberta','Recebida','Cancelada')), finance_id INTEGER UNIQUE REFERENCES finance(id), FOREIGN KEY(org_id,property_id) REFERENCES properties(org_id,id));
CREATE INDEX IF NOT EXISTS receivable_due ON receivables(org_id,status,due);
